@Entity
@Table(name = "orders")
public class Order {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "customer_email", nullable = false, length = 255)
    private String customerEmail;

    @Column(nullable = false)
    private OrderStatus status;

    protected Order() {}

    public Order(String customerEmail) {
        this.customerEmail = customerEmail;
        this.status = OrderStatus.PENDING;
    }
    // getters and setters omitted for brevity
}

@Service
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public void markShipped(Long orderId) {
        Order order = orderRepository.findById(orderId)
                .orElseThrow(() -> new OrderNotFoundException(orderId));
        order.setStatus(OrderStatus.SHIPPED);
        // method ends here -- no orderRepository.save(order) call at all
    }
}

@Service
public class OrderService {
    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional(readOnly = true)
    public Order getOrder(Long id) {
        return orderRepository.findById(id).orElseThrow();
    }
}

@RestController
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) { this.orderService = orderService; }

    @PostMapping("/orders/{id}/ship")
    public void ship(@PathVariable Long id) {
        Order order = orderService.getOrder(id);
        order.setStatus(OrderStatus.SHIPPED);   // looks identical to the working example above!
        // ... method ends; nothing was ever persisted, and there is no error anywhere
    }
}

