public interface OrderRepository extends JpaRepository<Order, Long> {

    List<Order> findByCustomerEmail(String email);

    List<Order> findByStatusAndCustomerEmail(OrderStatus status, String email);

    List<Order> findByTotalGreaterThanOrderByTotalDesc(BigDecimal minTotal);

    boolean existsByCustomerEmail(String email);
}

public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByCustomerName(String name);   // Order has customerEmail, not customerName
}

// Application fails to start:
// org.springframework.data.mapping.PropertyReferenceException:
// No property 'customerName' found for type 'Order'
// Did you mean: 'customerEmail'?

public interface OrderRepository extends JpaRepository<Order, Long> {

    // JPQL: navigates the mapped Customer association by field name
    @Query("select o from Order o join o.customer c where c.email = :email and o.status = :status")
    List<Order> findActiveOrdersForCustomer(@Param("email") String email, @Param("status") OrderStatus status);

    // Native SQL: refers directly to the actual join column and table names
    @Query(value = "SELECT o.* FROM orders o JOIN customers c ON o.customer_id = c.id WHERE c.email = :email AND o.status = :status",
           nativeQuery = true)
    List<Order> findActiveOrdersForCustomerNative(@Param("email") String email, @Param("status") String status);

