@Transactional(readOnly = true)
public int countAllBooks() {
    List<Author> authors = authorRepository.findAll();

    int total = 0;
    for (Author author : authors) {
        total += author.getBooks().size();
    }
    return total;
}

public interface AuthorRepository extends JpaRepository<Author, Long> {
    List<Author> findByCountry(String country);
}

@RestController
public class AuthorController {
    private final AuthorRepository authorRepository;

    public AuthorController(AuthorRepository authorRepository) { this.authorRepository = authorRepository; }

    @GetMapping("/authors")
    @Transactional(readOnly = true)
    public List<AuthorSummary> listByCountry(@RequestParam String country) {
        return authorRepository.findByCountry(country).stream()
                .map(a -> new AuthorSummary(a.getName(), a.getBooks().size()))
                .collect(Collectors.toList());
    }
}

